1	/**
2	 * CSVExportService
3	 *
4	 * Service for exporting expenses to CSV format
5	 * Specification: specs/specifications/expense-csv-export.md
6	 *
7	 * Traceable to:
8	 * - #{#exp2a} - CSV File Format Structure (IMPLEMENTED)
9	 * - #{#exp2b} - CSV Data Transformation (IMPLEMENTED)
10	 * - #{#exp3a} - CSV File Download Mechanism (IMPLEMENTED)
11	 * - #{#exp4a} - CSV Export Service Implementation (IMPLEMENTED)
12	 */
13	
14	import type { Expense } from './ExpenseService';
15	
16	/**
17	 * Date filter types for filename generation
18	 */
19	export type DateFilterType = 'all' | 'last_30' | 'last_90' | 'custom';
20	
21	/**
22	 * CSVExportService Class
23	 * Handles CSV generation, formatting, and download
24	 */
25	export class CSVExportService {
26		/**
27		 * Convert array of expenses to CSV format
28		 * #{#exp2a} CSV File Format Structure
29		 * #{#exp2b} CSV Data Transformation
30		 *
31		 * @param expenses - Array of expense objects to export
32		 * @returns CSV string with headers and data rows
33		 */
34		exportExpensesToCSV(expenses: Expense[]): string {
35			// #{#exp4a} Criterion 2: Validate input
36			if (expenses === null || expenses === undefined) {
37				throw new Error('Expenses array is required');
38			}
39	
40			// #{#exp2a} Criterion 2: CSV header row
41			const headers = ['Date', 'Merchant Name', 'Amount', 'Category'];
42			const csvLines: string[] = [headers.join(',')];
43	
44			// #{#exp4a} Criterion 3: Handle empty array - return headers only
45			if (expenses.length === 0) {
46				return csvLines.join('\n');
47			}
48	
49			// Process each expense into a CSV row
50			for (const expense of expenses) {
51				const row = this.formatExpenseRow(expense);
52				csvLines.push(row);
53			}
54	
55			// #{#exp2a} Criterion 9: Use LF line endings
56			return csvLines.join('\n');
57		}
58	
59		/**
60		 * Format a single expense as a CSV row
61		 * #{#exp2a} #{#exp2b}
62		 *
63		 * @param expense - Expense object to format
64		 * @returns CSV row string
65		 */
66		private formatExpenseRow(expense: Expense): string {
67			// #{#exp2b} Criterion 1: Format date as YYYY-MM-DD
68			const date = this.formatDate(expense.transaction_date);
69	
70			// #{#exp2b} Criterion 2: Sanitize merchant name (trim whitespace)
71			const merchantName = this.escapeCSVField(expense.merchant_name.trim());
72	
73			// #{#exp2b} Criterion 3, 4: Format amount (positive, 2 decimals)
74			const amount = this.formatAmount(expense.total_amount);
75	
76			// #{#exp2b} Criterion 6: Handle missing category
77			const category = this.escapeCSVField(expense.category_name?.trim() || '');
78	
79			return `${date},${merchantName},${amount},${category}`;
80		}
81	
82		/**
83		 * Format date to YYYY-MM-DD
84		 * #{#exp2a} Criterion 3
85		 * #{#exp2b} Criterion 1
86		 *
87		 * @param dateString - ISO date string or Date object
88		 * @returns YYYY-MM-DD formatted date
89		 */
90		private formatDate(dateString: string): string {
91			if (!dateString) {
92				return '';
93			}
94	
95			try {
96				// Handle both ISO strings and YYYY-MM-DD strings
97				// Use UTC to avoid timezone issues
98				let date: Date;
99	
100				if (dateString.includes('T')) {
101					// ISO timestamp with time - use UTC
102					date = new Date(dateString);
103				} else {
104					// Date-only string (YYYY-MM-DD) - treat as local date
105					const parts = dateString.split('-');
106					date = new Date(parseInt(parts[0]), parseInt(parts[1]) - 1, parseInt(parts[2]));
107				}
108	
109				const year = date.getFullYear();
110				const month = String(date.getMonth() + 1).padStart(2, '0');
111				const day = String(date.getDate()).padStart(2, '0');
112				return `${year}-${month}-${day}`;
113			} catch (error) {
114				// #{#exp4a} Criterion 8: Log warning, use fallback
115				console.warn(`Invalid date format: ${dateString}`, error);
116				return dateString.split('T')[0]; // Fallback: take date part of ISO string
117			}
118		}
119	
120		/**
121		 * Format amount to positive number with 2 decimal places
122		 * #{#exp2a} Criterion 5
123		 * #{#exp2b} Criterion 3, 4, 8
124		 *
125		 * @param amount - Amount value (may be negative)
126		 * @returns Formatted amount string
127		 */
128		private formatAmount(amount: number | null): string {
129			// A receipt whose amount OCR could not read stays blank rather than
130			// exporting a misleading 0.00
131			if (amount === null) return '';
132	
133			// #{#exp2b} Criterion 4: Convert negative to positive
134			const positiveAmount = Math.abs(amount);
135	
136			// #{#exp2b} Criterion 3: Round to 2 decimal places
137			// #{#exp2b} Criterion 8: Use period as decimal separator
138			return positiveAmount.toFixed(2);
139		}
140	
141		/**
142		 * Escape CSV field (handle commas, quotes, newlines)
143		 * #{#exp2a} Criterion 7, 8
144		 *
145		 * @param field - Field value to escape
146		 * @returns Escaped field value
147		 */
148		private escapeCSVField(field: string): string {
149			// #{#exp2a} Criterion 7: Quote fields containing commas
150			// #{#exp2a} Criterion 8: Escape quotes with double-quotes
151			if (field.includes(',') || field.includes('"') || field.includes('\n')) {
152				// Escape quotes by doubling them
153				const escaped = field.replace(/"/g, '""');
154				return `"${escaped}"`;
155			}
156			return field;
157		}
158	
159		/**
160		 * Generate appropriate filename for export
161		 * #{#exp3a} Criterion 2, 3, 4, 5
162		 *
163		 * @param filterType - Type of date filter applied
164		 * @param startDate - Start date of range (optional)
165		 * @param endDate - End date of range (optional)
166		 * @returns Filename string
167		 */
168		generateFilename(
169			filterType: DateFilterType,
170			startDate?: Date | string,
171			endDate?: Date | string
172		): string {
173			switch (filterType) {
174				case 'all':
175					// #{#exp3a} Criterion 3
176					return 'expenses_all_time.csv';
177	
178				case 'last_30':
179					// #{#exp3a} Criterion 4
180					return 'expenses_last_30_days.csv';
181	
182				case 'last_90':
183					// #{#exp3a} Criterion 4
184					return 'expenses_last_90_days.csv';
185	
186				case 'custom':
187					// #{#exp3a} Criterion 2
188					if (startDate && endDate) {
189						const start = this.formatDate(startDate.toString());
190						const end = this.formatDate(endDate.toString());
191	
192						// #{#exp3a} Special case: single day
193						if (start === end) {
194							return `expenses_${start}.csv`;
195						}
196	
197						return `expenses_${start}_to_${end}.csv`;
198					}
199					return 'expenses_custom.csv';
200	
201				default:
202					return 'expenses.csv';
203			}
204		}
205	
206		/**
207		 * #{#edf2a} Criterion 2: Filename for an Expenses-page export, chosen from the
208		 * currently-active filters. Date range wins over the category/uncategorized
209		 * filters (the page only lets one filter dimension drive the name at a time).
210		 *
211		 * `selectedCategoryNames` is the resolved name of every currently-selected
212		 * category (an unresolvable id contributes an empty string, which slugs to the
213		 * `filtered` fallback). Empty → falls through to the all-time name.
214		 */
215		expenseExportFilename(filters: {
216			dateFrom?: string;
217			dateTo?: string;
218			uncategorizedOnly?: boolean;
219			selectedCategoryNames?: string[];
220		}): string {
221			const { dateFrom, dateTo, uncategorizedOnly, selectedCategoryNames = [] } = filters;
222	
223			if (dateFrom && dateTo) return `expenses_${dateFrom}_to_${dateTo}.csv`;
224			if (dateFrom) return `expenses_from_${dateFrom}.csv`;
225			if (dateTo) return `expenses_to_${dateTo}.csv`;
226			if (uncategorizedOnly) return 'expenses_uncategorized.csv';
227	
228			if (selectedCategoryNames.length === 1) {
229				const slug = selectedCategoryNames[0].toLowerCase().replace(/\s+/g, '_') || 'filtered';
230				return `expenses_${slug}.csv`;
231			}
232			if (selectedCategoryNames.length > 1) return 'expenses_multiple_categories.csv';
233	
234			return this.generateFilename('all');
235		}
236	
237		/**
238		 * Trigger browser download of CSV content
239		 * #{#exp3a} Criterion 1, 5, 6, 7
240		 *
241		 * @param csvContent - CSV string to download
242		 * @param filename - Filename for download
243		 */
244		downloadCSV(csvContent: string, filename: string): void {
245			// #{#exp2a} Criterion 10: UTF-8 with BOM for Excel compatibility
246			const BOM = '\uFEFF';
247			const contentWithBOM = BOM + csvContent;
248	
249			// #{#exp3a} Criterion 5: Use text/csv MIME type
250			const blob = new Blob([contentWithBOM], { type: 'text/csv;charset=utf-8;' });
251	
252			// Create download link
253			const link = document.createElement('a');
254			const url = URL.createObjectURL(blob);
255	
256			link.setAttribute('href', url);
257			link.setAttribute('download', filename);
258			link.style.visibility = 'hidden';
259	
260			// #{#exp3a} Criterion 6: Don't navigate away
261			document.body.appendChild(link);
262			link.click();
263			document.body.removeChild(link);
264	
265			// Clean up object URL
266			URL.revokeObjectURL(url);
267		}
268	}
