/**
 * CSVExportService
 *
 * Service for exporting expenses to CSV format
 * Specification: specs/specifications/expense-csv-export.md
 *
 * Traceable to:
 * - #{#exp2a} - CSV File Format Structure (IMPLEMENTED)
 * - #{#exp2b} - CSV Data Transformation (IMPLEMENTED)
 * - #{#exp3a} - CSV File Download Mechanism (IMPLEMENTED)
 * - #{#exp4a} - CSV Export Service Implementation (IMPLEMENTED)
 */

import type { Expense } from './ExpenseService';

/**
 * Date filter types for filename generation
 */
export type DateFilterType = 'all' | 'last_30' | 'last_90' | 'custom';

/**
 * CSVExportService Class
 * Handles CSV generation, formatting, and download
 */
export class CSVExportService {
	/**
	 * Convert array of expenses to CSV format
	 * #{#exp2a} CSV File Format Structure
	 * #{#exp2b} CSV Data Transformation
	 *
	 * @param expenses - Array of expense objects to export
	 * @returns CSV string with headers and data rows
	 */
	exportExpensesToCSV(expenses: Expense[]): string {
		// #{#exp4a} Criterion 2: Validate input
		if (expenses === null || expenses === undefined) {
			throw new Error('Expenses array is required');
		}

		// #{#exp2a} Criterion 2: CSV header row
		const headers = ['Date', 'Merchant Name', 'Amount', 'Category'];
		const csvLines: string[] = [headers.join(',')];

		// #{#exp4a} Criterion 3: Handle empty array - return headers only
		if (expenses.length === 0) {
			return csvLines.join('\n');
		}

		// Process each expense into a CSV row
		for (const expense of expenses) {
			const row = this.formatExpenseRow(expense);
			csvLines.push(row);
		}

		// #{#exp2a} Criterion 9: Use LF line endings
		return csvLines.join('\n');
	}

	/**
	 * Format a single expense as a CSV row
	 * #{#exp2a} #{#exp2b}
	 *
	 * @param expense - Expense object to format
	 * @returns CSV row string
	 */
	private formatExpenseRow(expense: Expense): string {
		// #{#exp2b} Criterion 1: Format date as YYYY-MM-DD
		const date = this.formatDate(expense.transaction_date);

		// #{#exp2b} Criterion 2: Sanitize merchant name (trim whitespace)
		const merchantName = this.escapeCSVField(expense.merchant_name.trim());

		// #{#exp2b} Criterion 3, 4: Format amount (positive, 2 decimals)
		const amount = this.formatAmount(expense.total_amount);

		// #{#exp2b} Criterion 6: Handle missing category
		const category = this.escapeCSVField(expense.category_name?.trim() || '');

		return `${date},${merchantName},${amount},${category}`;
	}

	/**
	 * Format date to YYYY-MM-DD
	 * #{#exp2a} Criterion 3
	 * #{#exp2b} Criterion 1
	 *
	 * @param dateString - ISO date string or Date object
	 * @returns YYYY-MM-DD formatted date
	 */
	private formatDate(dateString: string): string {
		if (!dateString) {
			return '';
		}

		try {
			// Handle both ISO strings and YYYY-MM-DD strings
			// Use UTC to avoid timezone issues
			let date: Date;

			if (dateString.includes('T')) {
				// ISO timestamp with time - use UTC
				date = new Date(dateString);
			} else {
				// Date-only string (YYYY-MM-DD) - treat as local date
				const parts = dateString.split('-');
				date = new Date(parseInt(parts[0]), parseInt(parts[1]) - 1, parseInt(parts[2]));
			}

			const year = date.getFullYear();
			const month = String(date.getMonth() + 1).padStart(2, '0');
			const day = String(date.getDate()).padStart(2, '0');
			return `${year}-${month}-${day}`;
		} catch (error) {
			// #{#exp4a} Criterion 8: Log warning, use fallback
			console.warn(`Invalid date format: ${dateString}`, error);
			return dateString.split('T')[0]; // Fallback: take date part of ISO string
		}
	}

	/**
	 * Format amount to positive number with 2 decimal places
	 * #{#exp2a} Criterion 5
	 * #{#exp2b} Criterion 3, 4, 8
	 *
	 * @param amount - Amount value (may be negative)
	 * @returns Formatted amount string
	 */
	private formatAmount(amount: number | null): string {
		// A receipt whose amount OCR could not read stays blank rather than
		// exporting a misleading 0.00
		if (amount === null) return '';

		// #{#exp2b} Criterion 4: Convert negative to positive
		const positiveAmount = Math.abs(amount);

		// #{#exp2b} Criterion 3: Round to 2 decimal places
		// #{#exp2b} Criterion 8: Use period as decimal separator
		return positiveAmount.toFixed(2);
	}

	/**
	 * Escape CSV field (handle commas, quotes, newlines)
	 * #{#exp2a} Criterion 7, 8
	 *
	 * @param field - Field value to escape
	 * @returns Escaped field value
	 */
	private escapeCSVField(field: string): string {
		// #{#exp2a} Criterion 7: Quote fields containing commas
		// #{#exp2a} Criterion 8: Escape quotes with double-quotes
		if (field.includes(',') || field.includes('"') || field.includes('\n')) {
			// Escape quotes by doubling them
			const escaped = field.replace(/"/g, '""');
			return `"${escaped}"`;
		}
		return field;
	}

	/**
	 * Generate appropriate filename for export
	 * #{#exp3a} Criterion 2, 3, 4, 5
	 *
	 * @param filterType - Type of date filter applied
	 * @param startDate - Start date of range (optional)
	 * @param endDate - End date of range (optional)
	 * @returns Filename string
	 */
	generateFilename(
		filterType: DateFilterType,
		startDate?: Date | string,
		endDate?: Date | string
	): string {
		switch (filterType) {
			case 'all':
				// #{#exp3a} Criterion 3
				return 'expenses_all_time.csv';

			case 'last_30':
				// #{#exp3a} Criterion 4
				return 'expenses_last_30_days.csv';

			case 'last_90':
				// #{#exp3a} Criterion 4
				return 'expenses_last_90_days.csv';

			case 'custom':
				// #{#exp3a} Criterion 2
				if (startDate && endDate) {
					const start = this.formatDate(startDate.toString());
					const end = this.formatDate(endDate.toString());

					// #{#exp3a} Special case: single day
					if (start === end) {
						return `expenses_${start}.csv`;
					}

					return `expenses_${start}_to_${end}.csv`;
				}
				return 'expenses_custom.csv';

			default:
				return 'expenses.csv';
		}
	}

	/**
	 * #{#edf2a} Criterion 2: Filename for an Expenses-page export, chosen from the
	 * currently-active filters. Date range wins over the category/uncategorized
	 * filters (the page only lets one filter dimension drive the name at a time).
	 *
	 * `selectedCategoryNames` is the resolved name of every currently-selected
	 * category (an unresolvable id contributes an empty string, which slugs to the
	 * `filtered` fallback). Empty → falls through to the all-time name.
	 */
	expenseExportFilename(filters: {
		dateFrom?: string;
		dateTo?: string;
		uncategorizedOnly?: boolean;
		selectedCategoryNames?: string[];
	}): string {
		const { dateFrom, dateTo, uncategorizedOnly, selectedCategoryNames = [] } = filters;

		if (dateFrom && dateTo) return `expenses_${dateFrom}_to_${dateTo}.csv`;
		if (dateFrom) return `expenses_from_${dateFrom}.csv`;
		if (dateTo) return `expenses_to_${dateTo}.csv`;
		if (uncategorizedOnly) return 'expenses_uncategorized.csv';

		if (selectedCategoryNames.length === 1) {
			const slug = selectedCategoryNames[0].toLowerCase().replace(/\s+/g, '_') || 'filtered';
			return `expenses_${slug}.csv`;
		}
		if (selectedCategoryNames.length > 1) return 'expenses_multiple_categories.csv';

		return this.generateFilename('all');
	}

	/**
	 * Trigger browser download of CSV content
	 * #{#exp3a} Criterion 1, 5, 6, 7
	 *
	 * @param csvContent - CSV string to download
	 * @param filename - Filename for download
	 */
	downloadCSV(csvContent: string, filename: string): void {
		// #{#exp2a} Criterion 10: UTF-8 with BOM for Excel compatibility
		const BOM = '\uFEFF';
		const contentWithBOM = BOM + csvContent;

		// #{#exp3a} Criterion 5: Use text/csv MIME type
		const blob = new Blob([contentWithBOM], { type: 'text/csv;charset=utf-8;' });

		// Create download link
		const link = document.createElement('a');
		const url = URL.createObjectURL(blob);

		link.setAttribute('href', url);
		link.setAttribute('download', filename);
		link.style.visibility = 'hidden';

		// #{#exp3a} Criterion 6: Don't navigate away
		document.body.appendChild(link);
		link.click();
		document.body.removeChild(link);

		// Clean up object URL
		URL.revokeObjectURL(url);
	}
}
